// Room "P0 west bedroom" (interior designer's part): the inner air is x3..4, z14..20, floor layer y5, feet y6, head
// room to y8. The door (5, 6..7, 16) opens onto the cell (4, 6, 16), which stays clear. Two beds fill the south end
// (z19..20) with heads on the east partition (x5), because the west wall is windowed at z14..15 and z19..20 and the
// door sits on the only solid stretch (z16..18) in a 2-wide room: a bed row across the room would cut it in two.
// A barrel dresser under the north window, a red rug, and two lanterns (standing) light the room.
import { bed, layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  b: "barrel",
  f: "oak_fence",
  r: "red_carpet",
  p: "potted_poppy",
  l: ["lantern", { hanging: "false" }],
};

export function build(g) {
  // feet layer y6 (rows z14..20, columns x3..4): dresser, fence post, rug; beds are placed by bed() below
  // head layer y7: the flower pot on the dresser, the lanterns on the barrel and on the fence post
  layers(g, [3, 6, 14], LEGEND, [
    [
      "bb", // z14 dresser under the north window
      "..", // z15 lane
      "f.", // z16 lamp post at x3; (4,6,16) is the door's first cell and stays clear
      "rr", // z17 rug
      "rr", // z18 rug
      "..", // z19 beds
      "..", // z20 beds
    ],
    [
      "pl", // z14 pot and lantern on the dresser
      "..", // z15
      "l.", // z16 lantern on the lamp post
      "..", // z17
      "..", // z18
      "..", // z19
      "..", // z20
    ],
  ]);

  // two beds at the south end: foot at x3, head at x4 against the east partition (x5), pillow ends toward the wall
  bed(g, [3, 6, 19], "east", "red");
  bed(g, [3, 6, 20], "east", "blue");
}

