// never gets a bed. This places the same two halves with the same states, testing air either way.
function placeBed(g, [x, y, z], facing, color) {
  const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] }[facing];
  const free = (x, y, z) => !g.get(x, y, z) || /air$/.test(g.get(x, y, z).block);
